body.archive-page .arc--whole .arc-tags{
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin: 0;
  padding: 0 54px 18px;
  border-bottom: var(--arc-rw, 1px) solid var(--nc-rule, #D6D6D6);
  font-family: var(--byline-face, 'Work Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif);
